From 547c4b547e07dcc60874b6ef6252dd49ff74aec1 Mon Sep 17 00:00:00 2001
From: Florian Westphal <fw@strlen.de>
Date: Mon, 20 Apr 2015 12:35:47 +0200
Subject: [PATCH] netfilter: bridge: fix NULL deref in physin/out ifindex
 helpers

Might not have an outdev yet. We'll oops when iface goes down while skbs
are still nfqueue'd:

RIP: 0010:[<ffffffff81422a2f>]  [<ffffffff81422a2f>] dev_cmp+0x4f/0x80
nfqnl_rcv_dev_event+0xe2/0x150
notifier_call_chain+0x53/0xa0

Fixes: c737b7c4510026 ("netfilter: bridge: add helpers for fetching physin/outdev")
Signed-off-by: Florian Westphal <fw@strlen.de>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

diff --git a/include/linux/netfilter_bridge.h b/include/linux/netfilter_bridge.h
index ab8f76dba668..f2fdb5a52070 100644
--- a/include/linux/netfilter_bridge.h
+++ b/include/linux/netfilter_bridge.h
@@ -39,12 +39,24 @@ static inline void br_drop_fake_rtable(struct sk_buff *skb)

 static inline int nf_bridge_get_physinif(const struct sk_buff *skb)
 {
-	return skb->nf_bridge ? skb->nf_bridge->physindev->ifindex : 0;
+	struct nf_bridge_info *nf_bridge;
+
+	if (skb->nf_bridge == NULL)
+		return 0;
+
+	nf_bridge = skb->nf_bridge;
+	return nf_bridge->physindev ? nf_bridge->physindev->ifindex : 0;
 }

 static inline int nf_bridge_get_physoutif(const struct sk_buff *skb)
 {
-	return skb->nf_bridge ? skb->nf_bridge->physoutdev->ifindex : 0;
+	struct nf_bridge_info *nf_bridge;
+
+	if (skb->nf_bridge == NULL)
+		return 0;
+
+	nf_bridge = skb->nf_bridge;
+	return nf_bridge->physoutdev ? nf_bridge->physoutdev->ifindex : 0;
 }

 static inline struct net_device *
-- 
2.25.1

Code statements:
```c
-	return skb->nf_bridge ? skb->nf_bridge->physindev->ifindex : 0;
+	if (skb->nf_bridge == NULL)
+		return 0;
+
+	nf_bridge = skb->nf_bridge;
+	return nf_bridge->physindev ? nf_bridge->physindev->ifindex : 0;

-	return skb->nf_bridge ? skb->nf_bridge->physoutdev->ifindex : 0;
+	if (skb->nf_bridge == NULL)
+		return 0;
+
+	nf_bridge = skb->nf_bridge;
+	return nf_bridge->physoutdev ? nf_bridge->physoutdev->ifindex : 0;
```

Code statements:
- return skb->nf_bridge ? skb->nf_bridge->physindev->ifindex : 0;
- return skb->nf_bridge ? skb->nf_bridge->physoutdev->ifindex : 0;

The code statements that lead to the bug are:
```c
return skb->nf_bridge ? skb->nf_bridge->physindev->ifindex : 0;
return skb->nf_bridge ? skb->nf_bridge->physoutdev->ifindex : 0;
```
Reason:
The dereferencing of `skb->nf_bridge` without checking if it is `NULL` can lead to a `NULL` pointer dereference when the network interface goes down while packets are still queued, causing a kernel crash (oops).

The code statements that fix the bug are:
```c
if (skb->nf_bridge == NULL)
    return 0;
nf_bridge = skb->nf_bridge;
return nf_bridge->physindev ? nf_bridge->physindev->ifindex : 0;
```
Reason:
The patch adds a check to ensure that `skb->nf_bridge` is not `NULL` before dereferencing it. This prevents the potential `NULL` pointer dereference and ensures safe access to the `physindev` and `physoutdev` members.

